class ActivationBlock {HHOOK hook_=nullptr;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int code,WPARAM wp,LPARAM lp)->LRESULT{return code==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,code,wp,lp);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate sidebar test");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
sct::core::DocumentState Source(){using namespace sct::core;Image image;image.Create(320,220);auto s=Document(std::move(image)).State();Annotation a;a.tool=Tool::Rectangle;a.rect={20,20,100,80};a.label=L"Rectangle A";s.objects.push_back(a);a.tool=Tool::Text;a.rect={120,30,240,90};a.text=L"Original text";a.label=L"Text B";s.objects.push_back(a);a.tool=Tool::Ellipse;a.rect={40,120,100,170};a.text.Empty();a.label=L"Ellipse C";s.objects.push_back(a);a.tool=Tool::Line;a.rect={260,150,300,150};a.points={{260,150},{300,150}};a.label=L"Line D";s.objects.push_back(a);return s;}
void Core(Check check){using namespace sct;const auto state=Source();auto grouped=core::composition::Group(state,{0,1});check(core::layers::Units(grouped)==core::composition::Indices({3,2,1}),"layer units are topmost-first and flat groups appear once");auto renamed=core::layers::Rename(grouped,{0},L"Group name");check(renamed.objects[0].label==L"Group name"&&renamed.objects[1].label==L"Group name"&&renamed.objects[2].label==state.objects[2].label&&renamed.base==state.base,"group rename preserves source/style and changes all and only group members");auto hidden=core::layers::Visibility(grouped,{1},true);check(hidden.objects[0].hidden&&hidden.objects[1].hidden&&!hidden.objects[2].hidden,"group visibility is atomic and leaves unrelated layers visible");core::Document document;document.Reset(hidden);check(document.HitTest({20,20},5)<0&&!core::layers::Visible(hidden,{0}),"hidden layers cannot be hit from canvas or reported as visible");
    CString error;core::Image actual,expected;auto removed=state;removed.objects.erase(removed.objects.begin(),removed.objects.begin()+2);check(services::RenderDocument(hidden,actual,error)&&services::RenderDocument(removed,expected,error)&&actual.pixels==expected.pixels,"hidden layers are omitted from actual composed/export pixels");auto targets=core::alignment::BuildTargets(hidden,{});check(std::find(targets.x.begin(),targets.x.end(),20)==targets.x.end()&&std::find(targets.x.begin(),targets.x.end(),240)==targets.x.end(),"hidden group edges are not added to snap targets");
    auto mixed=grouped;mixed.objects[1].hidden=true;targets=core::alignment::BuildTargets(mixed,{});check(std::find(targets.x.begin(),targets.x.end(),240)==targets.x.end()&&std::find(targets.x.begin(),targets.x.end(),20)!=targets.x.end(),"partially hidden group snap bounds use visible members only");
    auto locked=core::composition::Lock(grouped,{0},true);for(int command=0;command<3;++command){bool rejected=false;try{core::composition::Indices selected;if(command==0)core::layers::Rename(locked,{0},L"bad");if(command==1)core::layers::Visibility(locked,{0},true);if(command==2)core::layers::PlaceAbove(locked,{0},3,selected);}catch(const std::exception&){rejected=true;}check(rejected&&locked.objects[0].label==state.objects[0].label&&!locked.objects[0].hidden,"locked group rejects label/visibility/order changes transactionally");}
    core::composition::Indices selected;auto moved=core::layers::PlaceAbove(grouped,{0},3,selected);check(selected==core::composition::Indices({2,3})&&moved.objects[2].label==state.objects[0].label&&moved.objects[3].label==state.objects[1].label,"layer drag moves complete group above target without changing member order");moved=core::layers::PlaceAbove(grouped,{3},0,selected,false);check(selected==core::composition::Indices({0})&&moved.objects[0].label==state.objects[3].label&&moved.objects[1].group==moved.objects[2].group,"drop below a target group does not split it");document.Reset(state);document.Commit(hidden);check(document.Undo()&&!document.State().objects[0].hidden&&document.Redo()&&document.State().objects[1].hidden,"visibility changes retain ordinary undo/redo");
}
