    static void Measure(EditorFrame* page,EditorSidebar& side,Check check,std::ofstream& log){const auto saved=page->document_.State();auto stress=saved;stress.objects.resize(10000,stress.objects.front());for(auto& a:stress.objects){a.group=0;a.locked=false;a.hidden=false;a.label=L"Stress object";}page->document_.Reset(stress);page->selected_=-1;++page->revision_;std::vector<double> times;for(int i=0;i<5;++i){const auto start=std::chrono::steady_clock::now();side.Refresh(true);times.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());}std::sort(times.begin(),times.end());const auto start=std::chrono::steady_clock::now();size_t text=0;for(int i=0;i<1000;++i)text+=side.RowText(i*7%10000,i%3).GetLength();const double lookup=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();check(side.rows_.size()==10000&&side.list_.GetItemCount()==10000&&text>0&&side.counts_.front()==1,"10000-object virtual list caches group counts and serves rows without per-row document scans");log<<"METRIC sidebar10000_refresh_median_ms="<<times[2]<<" row1000_lookup_ms="<<lookup<<" samples=5; private local metadata operations, not physical input latency\n";page->document_.Reset(saved);page->selected_=-1;page->Changed();Drain(page);}
