    static void Drag(EditorSidebar& side,int from,int target,bool cancel,std::ofstream& log){auto* p=side.owner;p->SetSelection({from},false);NMLISTVIEW notice{};notice.hdr={side.list_.m_hWnd,SidebarList,LVN_BEGINDRAG};notice.iItem=Row(side,from);log<<"DRAG before live="<<side.LiveSelection()<<" locked="<<p->SelectionLocked()<<" revision="<<side.revision_<<"/"<<p->revision_<<"\n";side.SendMessage(WM_NOTIFY,SidebarList,reinterpret_cast<LPARAM>(&notice));CRect r;side.list_.GetItemRect(Row(side,target),r,LVIR_BOUNDS);CPoint point(r.CenterPoint().x,r.top+2);LVHITTESTINFO hit{};hit.pt=point;log<<"DRAG armed="<<side.dragging_<<" row="<<Row(side,target)<<" hit="<<side.list_.HitTest(&hit)<<" point="<<point.x<<","<<point.y<<"\n";side.list_.ClientToScreen(&point);side.ScreenToClient(&point);if(cancel){side.SendMessage(WM_CAPTURECHANGED);if(::GetCapture()==side.m_hWnd)::ReleaseCapture();}side.SendMessage(WM_LBUTTONUP,0,MAKELPARAM(point.x,point.y));log<<"DRAG after selected="<<p->selected_<<" revision="<<p->revision_<<"\n";}
