        CRect r;side.GetClientRect(r);CClientDC screen(&side);CDC dc;dc.CreateCompatibleDC(&screen);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=r.Width();info.bmiHeader.biHeight=-r.Height();info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* bits=nullptr;HBITMAP bitmap=CreateDIBSection(screen,&info,DIB_RGB_COLORS,&bits,nullptr,0);if(!bitmap)return false;auto old=::SelectObject(dc,bitmap);dc.FillSolidRect(r,GetSysColor(COLOR_BTNFACE));
