        paint(side,r);GdiFlush();core::Image image;image.Create(r.Width(),r.Height());memcpy(image.pixels.data(),bits,image.pixels.size());for(size_t i=3;i<image.pixels.size();i+=4)image.pixels[i]=255;::SelectObject(dc,old);::DeleteObject(bitmap);CString error;std::vector<BYTE> bytes;return services::EncodeImage(image,L"png",100,bytes,error)&&services::WriteBytes(path.c_str(),bytes,error);
